// Convert Polygon2d to CGAL polygon
internal::Polygon_2 cgalP1, cgalP2;
for (const Point2d& p : P1) {
    cgalP1.push_back(internal::Point_2(p.x(), p.y()));
}
for (const Point2d& p : P2) {
    cgalP2.push_back(internal::Point_2(p.x(), p.y()));
}

// Compute difference
internal::Pwh_list_2 result;
CGAL::difference(cgalP1, cgalP2, std::back_inserter(result));

// Convert result to PolygonWithHoles2d
std::vector<PolygonWithHoles2d> output;
for (const internal::Polygon_with_holes_2& pwh : result) {
    PolygonWithHoles2d polyHole;

    // Convert outer boundary
    const internal::Polygon_2& outer = pwh.outer_boundary();
    std::vector<Point2d> outerPoints;
    for (auto it = outer.vertices_begin(); it != outer.vertices_end(); ++it) {
        double x, y;
        internal::getCoordinates(*it, x, y);
        outerPoints.emplace_back(x, y);
    }
    polyHole.outer = outerPoints;

    // Convert holes
    for (auto hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        std::vector<Point2d> holePoints;
        for (auto it = hit->vertices_begin(); it != hit->vertices_end(); ++it) {
            double x, y;
            internal::getCoordinates(*it, x, y);
            holePoints.emplace_back(x, y);
        }
        polyHole.holes.push_back(holePoints);
    }

    output.push_back(polyHole);
}

return output;

